// `root_element` is the block's shadow root, supplied by frappe.
const links = Array.from(root_element.querySelectorAll('.ws-link'));

function currentSlug() {
	// v16 serves the desk at /desk/<workspace>; /app/<workspace> still redirects
	// there, so accept either base.
	const parts = window.location.pathname.split('/').filter(Boolean);
	const isDesk = parts[0] === 'desk' || parts[0] === 'app';
	return isDesk && parts[1] ? parts[1].toLowerCase() : '';
}

function markCurrent() {
	const slug = currentSlug();
	links.forEach((link) => {
		const isCurrent = link.dataset.slug === slug;
		link.classList.toggle('is-current', isCurrent);
		if (isCurrent) {
			link.setAttribute('aria-current', 'page');
		} else {
			link.removeAttribute('aria-current');
		}
	});
}

links.forEach((link) => {
	link.addEventListener('click', (event) => {
		// Shadow DOM retargets clicks, so frappe's global anchor handler never
		// sees this <a>. Route by hand, otherwise every click is a full reload.
		event.preventDefault();
		if (link.classList.contains('is-current')) return;
		// Deferred: routing synchronously would rebuild the workspace, and this
		// block, while the click that triggered it is still being dispatched.
		setTimeout(() => frappe.set_route(link.dataset.slug), 0);
	});
});

markCurrent();

// Keep the highlight right if the desk swaps workspaces without rebuilding
// this block. Bails out once the block's host element is detached.
frappe.router.on('change', () => {
	if (root_element.host && root_element.host.isConnected) markCurrent();
});

style:
/* Rendered inside a shadow root with desk.bundle.css linked. Frappe's CSS
   variables inherit across the shadow boundary, so they resolve here, and these
   class names cannot leak out.

   Styled after the pill buttons on the churchit marketing site: fully rounded,
   tinted, lifting a little on hover, with the site's indigo/violet/pink
   gradient marking the workspace you are on. */
.ws-header {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px;
	padding-bottom: 10px;
	margin-bottom: 4px;
	/* The site's gradient as a 1px rule, fading out to the right, instead of a
	   flat border. Drawn as a background so it can be a gradient at all. */
	background-image: linear-gradient(
		90deg,
		rgba(99, 102, 241, 0.55) 0%,
		rgba(139, 92, 246, 0.45) 40%,
		rgba(236, 72, 153, 0.35) 70%,
		transparent 100%
	);
	background-repeat: no-repeat;
	background-position: left bottom;
	background-size: 100% 1px;
}

/* One tint per module. These are frappe's own background/foreground pairs, and
   the dark theme redefines both halves, so each pill stays legible in either
   theme without this block having to detect the theme itself — it cannot, since
   :root matches nothing inside a shadow root and :host-context() is not
   supported everywhere. Operations and Settings intentionally fall through to
   the neutral default below.

   Every pair here clears 4.5:1 in both themes. Two of frappe's pairs do not and
   so go unused: yellow (3.9:1 light, 4.1:1 dark) and light-blue against its own
   text-on-light-blue (4.1:1 light) — hence Web Site pairing the light-blue tint
   with the stronger text-on-blue ink instead. */
.ws-link[data-slug="communications"] { --ws-bg: var(--bg-cyan); --ws-fg: var(--text-on-cyan); }
.ws-link[data-slug="finances"] { --ws-bg: var(--bg-green); --ws-fg: var(--text-on-green); }
.ws-link[data-slug="foundations"] { --ws-bg: var(--bg-blue); --ws-fg: var(--text-on-blue); }
.ws-link[data-slug="ministries"] { --ws-bg: var(--bg-red); --ws-fg: var(--text-on-red); }
.ws-link[data-slug="missions"] { --ws-bg: var(--bg-dark-blue); --ws-fg: var(--text-on-dark-blue); }
.ws-link[data-slug="people"] { --ws-bg: var(--bg-purple); --ws-fg: var(--text-on-purple); }
.ws-link[data-slug="prayers"] { --ws-bg: var(--bg-pink); --ws-fg: var(--text-on-pink); }
.ws-link[data-slug="study"] { --ws-bg: var(--bg-orange); --ws-fg: var(--text-on-orange); }
.ws-link[data-slug="web-site"] { --ws-bg: var(--bg-light-blue); --ws-fg: var(--text-on-blue); }

.ws-link {
	display: inline-flex;
	align-items: center;
	gap: 5px;
	padding: 4px 11px;
	border: 1px solid transparent;
	border-radius: 999px;
	font-size: var(--text-sm);
	font-weight: 500;
	line-height: 1.5;
	white-space: nowrap;
	text-decoration: none;
	background-color: var(--ws-bg, var(--bg-gray));
	color: var(--ws-fg, var(--text-on-gray));
	transition: transform 0.12s ease, box-shadow 0.15s ease, filter 0.12s ease;
}

.ws-link:hover,
.ws-link:focus-visible {
	color: var(--ws-fg, var(--text-on-gray));
	text-decoration: none;
	transform: translateY(-1px);
	box-shadow: var(--shadow-sm);
	filter: saturate(1.3);
}

.ws-link:focus-visible {
	outline: 2px solid var(--brand-color);
	outline-offset: 2px;
}

.ws-icon {
	font-size: 0.95em;
	line-height: 1;
}

/* The workspace you are already on: the site's primary-button gradient, shown
   for orientation but not a link. background-origin keeps the gradient aligned
   to the outer edge so the 1px transparent border leaves no colour fringe.

   Same indigo -> violet -> pink ramp as .btn-primary on the site, one step
   darker (the 600s, not the 500s). White on the site's 500 ramp is 3.5:1 at the
   pink end, which is fine for its 1rem buttons but not for 12px desk text; the
   600s keep the look and clear 4.6:1 across every stop. */
.ws-link.is-current {
	background-image: linear-gradient(120deg, #4f46e5 0%, #7c3aed 50%, #db2777 100%);
	background-origin: border-box;
	color: #fff;
	font-weight: 600;
	box-shadow: 0 6px 16px -8px rgba(79, 70, 229, 0.9);
	cursor: default;
	pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
	.ws-link {
		transition: none;
	}

	.ws-link:hover,
	.ws-link:focus-visible {
		transform: none;
	}
}
